style.css:
@-moz-document domain("roblox.com") {
/* Main play button */
    .btn-common-play-game-lg,
    .btn-common-play-game-sm,
    .btn-primary-md[data-testid="game-detail-play-button"],
    .game-calls-to-action .btn-primary-lg,
    .game-calls-to-action .btn-primary-md {
        background-color: #02b757 !important;
        border-color: #029a48 !important;
    }

    /* Hover state */
    .btn-common-play-game-lg:hover,
    .btn-common-play-game-sm:hover,
    .btn-primary-md[data-testid="game-detail-play-button"]:hover,
    .game-calls-to-action .btn-primary-lg:hover,
    .game-calls-to-action .btn-primary-md:hover {
        background-color: #029a48 !important;
        border-color: #028a40 !important;
    }
}
